CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE actors (id uuid PRIMARY KEY, issuer text NOT NULL, subject text NOT NULL, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('human','agent')), system_admin boolean NOT NULL DEFAULT false, UNIQUE(issuer,subject));
CREATE TABLE projects (id uuid PRIMARY KEY, key text UNIQUE NOT NULL, name text NOT NULL, instructions text NOT NULL DEFAULT '', policy text NOT NULL CHECK(policy IN ('self','independent','human')), revision integer NOT NULL CHECK(revision>0), ticket_seq integer NOT NULL DEFAULT 0, event_seq bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL);
CREATE TABLE members (id text PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), actor_id uuid NOT NULL REFERENCES actors(id), role text NOT NULL CHECK(role IN ('reader','contributor','verifier','admin')), UNIQUE(project_id,actor_id));
CREATE TABLE tickets (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), key text UNIQUE NOT NULL, title text NOT NULL, description text NOT NULL, status text NOT NULL CHECK(status IN ('backlog','ready','in_progress','in_review','done','cancelled')), priority integer NOT NULL CHECK(priority BETWEEN 1 AND 5), labels text[] NOT NULL DEFAULT '{}', capabilities text[] NOT NULL DEFAULT '{}', assignee_id uuid REFERENCES actors(id), parent_id uuid REFERENCES tickets(id), revision integer NOT NULL CHECK(revision>0), requirements_revision integer NOT NULL CHECK(requirements_revision>0), created_by uuid NOT NULL REFERENCES actors(id), approved_submission_id uuid, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(project_id,id));
CREATE INDEX tickets_queue ON tickets(project_id,status,priority,created_at,id);
CREATE INDEX tickets_parent ON tickets(project_id,parent_id);
CREATE TABLE criteria (id uuid PRIMARY KEY, project_id uuid NOT NULL, ticket_id uuid NOT NULL, text text NOT NULL, position integer NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE INDEX criteria_ticket ON criteria(project_id,ticket_id,position);
CREATE TABLE links (id text PRIMARY KEY, project_id uuid NOT NULL, source_id uuid NOT NULL, target_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('blocks','related')), CHECK(source_id<>target_id), FOREIGN KEY(project_id,source_id) REFERENCES tickets(project_id,id), FOREIGN KEY(project_id,target_id) REFERENCES tickets(project_id,id), UNIQUE(source_id,target_id,kind));
CREATE INDEX links_target ON links(project_id,target_id,kind);
CREATE TABLE notes (id uuid PRIMARY KEY, project_id uuid NOT NULL, ticket_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES actors(id), kind text NOT NULL CHECK(kind IN ('comment','checkpoint','question','answer')), body text NOT NULL, blocking boolean NOT NULL DEFAULT false, answer_to uuid REFERENCES notes(id), metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE INDEX notes_ticket ON notes(project_id,ticket_id,created_at,id);
CREATE TABLE claims (id uuid PRIMARY KEY, project_id uuid NOT NULL, ticket_id uuid UNIQUE NOT NULL, actor_id uuid NOT NULL REFERENCES actors(id), token uuid NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE TABLE submissions (id uuid PRIMARY KEY, project_id uuid NOT NULL, ticket_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES actors(id), requirements_revision integer NOT NULL, evidence jsonb NOT NULL, summary text NOT NULL, created_at timestamptz NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE INDEX submissions_ticket ON submissions(project_id,ticket_id,created_at);
CREATE TABLE reviews (id uuid PRIMARY KEY, project_id uuid NOT NULL, ticket_id uuid NOT NULL, submission_id uuid NOT NULL REFERENCES submissions(id), actor_id uuid NOT NULL REFERENCES actors(id), decision text NOT NULL CHECK(decision IN ('approve','request_changes')), feedback text NOT NULL, created_at timestamptz NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE TABLE knowledge (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), title text NOT NULL, body text NOT NULL, kind text NOT NULL CHECK(kind IN ('policy','decision','runbook','architecture','note')), revision integer NOT NULL CHECK(revision>0), archived boolean NOT NULL DEFAULT false, actor_id uuid NOT NULL REFERENCES actors(id), updated_at timestamptz NOT NULL);
CREATE INDEX knowledge_project ON knowledge(project_id,archived,id);
CREATE TABLE events (id text PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), seq bigint NOT NULL, actor_id uuid NOT NULL REFERENCES actors(id), type text NOT NULL, entity_id text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL, UNIQUE(project_id,seq));
CREATE TABLE receipts (id text PRIMARY KEY, project_id uuid REFERENCES projects(id), actor_id uuid NOT NULL REFERENCES actors(id), operation text NOT NULL, input_hash text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE jobs (id text PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), entity_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('ticket','knowledge')), revision integer NOT NULL, attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL, locked_until timestamptz, lock_token uuid, last_error text);
CREATE INDEX jobs_available ON jobs(available_at,locked_until);
CREATE TABLE search_documents (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), kind text NOT NULL, revision integer NOT NULL, title text NOT NULL, text text NOT NULL, archived boolean NOT NULL, search tsvector GENERATED ALWAYS AS (to_tsvector('english', title || ' ' || text)) STORED);
CREATE INDEX search_text ON search_documents USING gin(search);
CREATE INDEX search_project ON search_documents(project_id,archived);
CREATE TABLE search_profiles (id text PRIMARY KEY, model text NOT NULL, dimensions integer NOT NULL CHECK(dimensions BETWEEN 1 AND 2000));
CREATE TABLE search_vectors (document_id uuid NOT NULL REFERENCES search_documents(id) ON DELETE CASCADE, profile_id text NOT NULL REFERENCES search_profiles(id), revision integer NOT NULL, embedding vector NOT NULL, PRIMARY KEY(document_id,profile_id));
